(()=>{const w=document.getElementById('weekday-minutes'),h=document.getElementById('weekend-minutes'),r=document.getElementById('reserve-percent'),o=document.getElementById('time-result');const fmt=n=>`${Math.floor(n/60)}時間${n%60}分`;function update(){if([w,h,r].some(x=>x.value===''||!x.validity.valid)){o.textContent='時間は0〜1440の整数、割合は0〜100の整数で入力してください。';return;}const total=Number(w.value)*5+Number(h.value)*2,reserve=Math.round(total*Number(r.value)/100);o.textContent=`合計${fmt(total)}。予備${fmt(reserve)}。課題を入れる時間${fmt(total-reserve)}。`;}[w,h,r].forEach(x=>x.addEventListener('input',update));document.getElementById('print-sheet').addEventListener('click',()=>window.print());update();})();